    content = f.read()

old = '''// validIntervalsList renders validPollIntervals (internal/email/config.go)
// as a single comma-separated string, sorted ascending by duration rather
// than by map iteration order, which Go leaves undefined. Both
// config-validation error paths in this file build their "valid: ..." text
// from this one function, so adding a value to validPollIntervals can never
// leave either string stale — a third hand-maintained copy is exactly how
// that drift happened before.
func validIntervalsList() string {
\ttype entry struct {
\t\tname string
\t\td    time.Duration
\t}
\tentries := make([]entry, 0, len(validPollIntervals))
\tfor name, d := range validPollIntervals {
\t\tentries = append(entries, entry{name, d})
\t}
\tsort.Slice(entries, func(i, j int) bool { return entries[i].d < entries[j].d })
\tnames := make([]string, len(entries))
\tfor i, e := range entries {
\t\tnames[i] = e.name
\t}
\treturn strings.Join(names, ", ")
}'''

new = '''// PollIntervals returns the keys of validPollIntervals
// (internal/email/config.go), sorted ascending by duration rather than by
// map iteration order, which Go leaves undefined. Exported so other
// packages — internal/mcp's set_poll_interval tool, in particular — can
// build their own interval-set text from the same source instead of
// hand-maintaining a parallel copy, which is exactly how this set drifted
// before.
func PollIntervals() []string {
\ttype entry struct {
\t\tname string
\t\td    time.Duration
\t}
\tentries := make([]entry, 0, len(validPollIntervals))
\tfor name, d := range validPollIntervals {
\t\tentries = append(entries, entry{name, d})
\t}
\tsort.Slice(entries, func(i, j int) bool { return entries[i].d < entries[j].d })
\tnames := make([]string, len(entries))
\tfor i, e := range entries {
\t\tnames[i] = e.name
\t}
\treturn names
}

// PollIntervalList renders PollIntervals as a single comma-separated
// string. Both config-validation error paths in this file build their
// "valid: ..." text from this one function, so adding a value to
// validPollIntervals can never leave either string stale.
func PollIntervalList() string {
\treturn strings.Join(PollIntervals(), ", ")
}'''

assert old in content, 'function block not found'
content = content.replace(old, new)

content = content.replace(
    'return fmt.Errorf("invalid poll_interval %q in config (valid: %s, n=disable)", cfg.PollInterval, validIntervalsList())',
    'return fmt.Errorf("invalid poll_interval %q in config (valid: %s, n=disable)", cfg.PollInterval, PollIntervalList())'
)
content = content.replace(
    'return "invalid poll interval " + e.Value + ": must be " + validIntervalsList() + ", or n"',
    'return "invalid poll interval " + e.Value + ": must be " + PollIntervalList() + ", or n"'
)

with open(path, 'w') as f:
    f.write(content)
print('done')
PYEOF

